use std::collections::BTreeMap;

use velnor_gen::{
    Drift, ExternalWorkflowError, GenerateError, drift, expected_files, external_skips,
};
use velnor_model::{RepoPath, RepoView};
use velnor_render::seal;

use crate::base_save::pinned;
use crate::facts::TestResult;

const HAND_WRITTEN: &str = "name: Image\non: pull_request\n";
const LISTED: &str = ".github/workflows/image.yml";
const GENERATED_HEADER: &str =
    "# Generated by velnor-gen. Change .velnor/rust-ci.toml and run `velnor-gen generate`.\n";

type Disk = BTreeMap<RepoPath, Vec<u8>>;

fn config(paths: &str) -> String {
    format!("external_workflows = [{paths}]\n")
}

fn one(path: &str, text: &str) -> Result<Disk, Box<dyn std::error::Error>> {
    Ok(BTreeMap::from([(
        RepoPath::new(path)?,
        text.as_bytes().to_vec(),
    )]))
}

fn view_of(version: &str, text: &str) -> Result<RepoView, Box<dyn std::error::Error>> {
    Ok(pinned(version, text)?)
}

#[test]
fn a_listed_unowned_workflow_is_not_drift_and_an_unlisted_one_still_is() -> TestResult {
    let view = view_of("0.1.108", &config(&format!("\"{LISTED}\"")))?;
    let files = one(LISTED, HAND_WRITTEN)?;
    let expected = expected_files(&view)?;
    let skipped = external_skips(&view, &files)?;
    let drifts = drift(&expected, &files, &skipped);
    assert!(
        !drifts.iter().any(|d| d.path().as_str() == LISTED),
        "{drifts:?}"
    );

    let view = view_of("0.1.108", "")?;
    let drifts = drift(&expected, &files, &external_skips(&view, &files)?);
    let unmarked = drifts
        .iter()
        .find(|d| d.path().as_str() == LISTED)
        .ok_or("the unlisted file is not reported")?;
    assert!(matches!(unmarked, Drift::Unmarked(_)), "{unmarked:?}");
    assert!(
        unmarked.to_string().contains("external_workflows"),
        "{unmarked}"
    );
    Ok(())
}

#[test]
fn a_listed_path_that_does_not_exist_is_refused() -> TestResult {
    let view = view_of("0.1.108", &config(&format!("\"{LISTED}\"")))?;
    assert_eq!(
        external_skips(&view, &BTreeMap::new()).err(),
        Some(GenerateError::ExternalWorkflow(
            ExternalWorkflowError::Missing(RepoPath::new(LISTED)?)
        ))
    );
    Ok(())
}

#[test]
fn a_listed_path_velnor_gen_writes_is_refused() -> TestResult {
    let generated = ".github/workflows/rust-ci.yml";
    let view = view_of("0.1.108", &config(&format!("\"{generated}\"")))?;
    assert_eq!(
        external_skips(&view, &one(generated, HAND_WRITTEN)?).err(),
        Some(GenerateError::ExternalWorkflow(
            ExternalWorkflowError::Collision(RepoPath::new(generated)?)
        ))
    );
    Ok(())
}

#[test]
fn a_listed_file_that_carries_the_velnor_gen_header_is_refused_as_generated() -> TestResult {
    let stale = ".github/workflows/old.yml";
    let view = view_of("0.1.108", &config(&format!("\"{stale}\"")))?;
    let files = one(stale, &seal(GENERATED_HEADER, "name: Old\n"))?;
    assert_eq!(
        external_skips(&view, &files).err(),
        Some(GenerateError::ExternalWorkflow(
            ExternalWorkflowError::Generated(RepoPath::new(stale)?)
        ))
    );
    Ok(())
}

#[test]
fn external_workflows_is_refused_below_the_helper_that_accepts_it() -> TestResult {
    let view = view_of("0.1.107", &config(&format!("\"{LISTED}\"")))?;
    let error = expected_files(&view).err();
    assert!(
        matches!(
            error,
            Some(GenerateError::ExternalWorkflow(
                ExternalWorkflowError::HelperTooOld(_)
            ))
        ),
        "{error:?}"
    );
    Ok(())
}

#[test]
fn external_workflows_accepts_only_yaml_files_directly_under_the_workflow_directory() -> TestResult
{
    for bad in [
        ".github/image.yml",
        ".github/workflows/nested/image.yml",
        ".github/workflows/image.txt",
        "Dockerfile",
        ".github/workflows/image.yml/../../x.yml",
    ] {
        let view = view_of("0.1.108", &config(&format!("\"{bad}\"")))?;
        assert!(expected_files(&view).is_err(), "{bad} was accepted");
    }
    let view = view_of("0.1.108", &config(&format!("\"{LISTED}\"")))?;
    assert!(expected_files(&view).is_ok());
    Ok(())
}
